714	/* ── Componente principal ────────────────────────────────────────── */
715	const MenuCatalogProductBrowse = () => {
716	  const navigate = useNavigate();
717	  const { isAuthenticated, isAdmin, isRestaurantOwner, isMotoboy, signOut, userProfile } = useAuth();
718	
719	  const [restaurantes, setRestaurantes] = useState([]);
720	  const [produtos, setProdutos]         = useState([]);
721	  const [combos, setCombos]             = useState([]);
722	  const [categorias, setCategorias]     = useState(CATEGORIAS_FALLBACK);
723	  const [tagsCatalogo, setTagsCatalogo] = useState([]); // tags ativas do admin
724	  const [loading, setLoading]           = useState(true);
725	  const [loadProd, setLoadProd]         = useState(true);
726	  const [erro, setErro]                 = useState(null);
727	  const [busca, setBusca]               = useState('');
728	  const [catAtiva, setCatAtiva]         = useState(null);
729	  const [viewMode, setViewMode]         = useState('grid');
730	  const [badgeCount, setBadgeCount]     = useState(() => cartCount());
731	  const [badgeTotal, setBadgeTotal]     = useState(() => cartTotal());
732	  const [perfilCliente, setPerfilCliente] = useState(null);
733	  const [marca, setMarca] = useState(DEFAULT_MARCA);
734	
735	  useEffect(() => {
736	    fetch(apiPath('/api/r/branding'))
737	      .then((r) => r.json())
738	      .then((d) => setMarca((m) => ({ ...m, ...d })))
739	      .catch(() => {});
740	  }, []);
741	
742	  // Filtro geográfico — localização automática (GPS do navegador) + filtros manuais
743	  // de Estado/Cidade/Bairro/CEP. Sem filtro manual ativo, a localização já limita a
744	  // lista ao raio escolhido automaticamente (cliente não precisa mexer em nada).
745	  const [localizacao, setLocalizacao]     = useState(null); // { lat, lng, accuracy } | null
746	  const [statusLocalizacao, setStatusLocalizacao] = useState('pedindo'); // pedindo|ok|negado|indisponivel
747	  const [raioKm, setRaioKm]               = useState(15);
748	  const [locaisFiltro, setLocaisFiltro]   = useState([]);
749	  const [filtroEstado, setFiltroEstado]   = useState('');
750	  const [filtroCidade, setFiltroCidade]   = useState('');
751	  const [filtroBairro, setFiltroBairro]   = useState('');
752	  const [filtroCep, setFiltroCep]         = useState('');
753	
754	  const pedirLocalizacao = () => {
755	    if (!navigator.geolocation) { setStatusLocalizacao('indisponivel'); return; }
756	    setStatusLocalizacao('pedindo');
757	    navigator.geolocation.getCurrentPosition(
758	      (pos) => {
759	        setLocalizacao({ lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy });
760	        setStatusLocalizacao('ok');
761	      },
762	      () => setStatusLocalizacao('negado'),
763	      { timeout: 8000, enableHighAccuracy: true, maximumAge: 0 },
764	    );
765	  };
766	
767	  const limparFiltrosGeo = () => {
768	    setFiltroEstado(''); setFiltroCidade(''); setFiltroBairro(''); setFiltroCep('');
769	  };
770	
771	  const temFiltroManual = !!(filtroEstado || filtroCidade || filtroBairro || filtroCep);
772	  // Esconde raios menores que a precisão real do GPS (localizacao.accuracy, em metros) —
773	  // uma opção de 20m/50m com GPS impreciso (rede/wifi) nunca bateria com nada, ilusória.
774	  const raioOpcoesDisponiveis = localizacao?.accuracy
775	    ? RAIO_OPCOES.filter((km) => km === 0 || km * 1000 >= localizacao.accuracy)
776	    : RAIO_OPCOES;
777	  const estadosDisponiveis = [...new Set(locaisFiltro.map((l) => l.state).filter(Boolean))].sort();
778	  const cidadesDisponiveis = [...new Set(
779	    locaisFiltro.filter((l) => !filtroEstado || l.state === filtroEstado).map((l) => l.city).filter(Boolean),
780	  )].sort();
781	  const bairrosDisponiveis = [...new Set(
782	    locaisFiltro
783	      .filter((l) => (!filtroEstado || l.state === filtroEstado) && (!filtroCidade || l.city === filtroCidade))
784	      .map((l) => l.neighborhood).filter(Boolean),
785	  )].sort();
786	
787	  const handleAddToCart = (produto, restaurante) => {
788	    cartAdd(produto, restaurante);
789	    setBadgeCount(cartCount());
790	    setBadgeTotal(cartTotal());
791	  };
792	
793	  const handleIrCheckout = () => {
794	    if (!isAuthenticated()) {
795	      sessionStorage.setItem('pending_multi_cart', '1');
796	      navigate('/customer-registration-login', { state: { from: '/shopping-cart-checkout' } });
797	      return;
798	    }
799	    navigate('/shopping-cart-checkout', { state: { multiCart: true } });
800	  };
801	
802	  const mediaNota = restaurantes.length > 0
803	    ? restaurantes.reduce((acc, r) => acc + (r.nota ?? 4.5), 0) / restaurantes.length
804	    : 0;
805	
806	  useEffect(() => {
807	    pedirLocalizacao();
808	    // Rede de segurança: se o navegador nunca resolver o pedido de permissão (usuário
809	    // deixa o diálogo aberto), não trava a home esperando pra sempre.
810	    const fallback = setTimeout(() => setStatusLocalizacao((s) => (s === 'pedindo' ? 'negado' : s)), 10000);
811	
812	    fetch(apiPath('/api/r/produtos'))
813	      .then((r) => r.json())
814	      .then((d) => setProdutos(d.produtos ?? []))
815	      .catch(() => setProdutos([]))
816	      .finally(() => setLoadProd(false));
817	
818	    fetch(apiPath('/api/r/combos'))
819	      .then((r) => r.json())
820	      .then((d) => setCombos(d.combos ?? []))
821	      .catch(() => setCombos([]));
822	
823	    fetch(apiPath('/api/categorias/globais'))
824	      .then((r) => r.json())
825	      .then((d) => { const cats = d.categorias ?? []; if (cats.length > 0) setCategorias(cats); })
826	      .catch(() => {});
827	
828	    fetch(apiPath('/api/tags'))
829	      .then((r) => r.json())
830	      .then((d) => setTagsCatalogo(d.tags ?? []))
831	      .catch(() => {});
832	
833	    fetch(apiPath('/api/r/filtros'))
834	      .then((r) => r.json())
835	      .then((d) => setLocaisFiltro(d.locais ?? []))
836	      .catch(() => {});
837	
838	    return () => clearTimeout(fallback);
839	  }, []);
840	
841	  // Foto/nome do cliente pro avatar do cabeçalho — só cliente comum, dono de
842	  // restaurante/admin já têm seus próprios botões de painel.
843	  useEffect(() => {
844	    if (!isAuthenticated() || isAdmin() || isRestaurantOwner()) { setPerfilCliente(null); return; }
845	    getPerfil().then(setPerfilCliente).catch(() => {});
846	  }, [userProfile?.id, userProfile?.role]);
847	
848	  // Se a precisão do GPS piorar (ou não vier mais tão boa) e o raio selecionado sumir
849	  // da lista disponível, sobe pro menor raio que ainda é real — nunca deixa um valor
850	  // inválido/ilusório selecionado.
851	  useEffect(() => {
852	    if (!raioOpcoesDisponiveis.includes(raioKm)) {
853	      setRaioKm(raioOpcoesDisponiveis.find((km) => km !== 0) ?? raioOpcoesDisponiveis[0]);
854	    }
855	  }, [raioOpcoesDisponiveis]);
856	
857	  // Busca restaurantes toda vez que localização/raio/filtros geográficos mudam — o
858	  // servidor já filtra/ordena por distância, sem filtro manual ativo o raio entra
859	  // sozinho assim que o GPS responde (automático, sem o cliente mexer em nada).
860	  useEffect(() => {
861	    if (statusLocalizacao === 'pedindo' && !temFiltroManual) return; // espera o GPS antes do 1º fetch
862	
863	    setLoading(true);
864	    const params = new URLSearchParams();
865	    if (filtroEstado) params.set('state', filtroEstado);
866	    if (filtroCidade) params.set('city', filtroCidade);
867	    if (filtroBairro) params.set('neighborhood', filtroBairro);
868	    if (filtroCep) params.set('cep', filtroCep);
869	    if (localizacao) {
870	      params.set('lat', String(localizacao.lat));
871	      params.set('lng', String(localizacao.lng));
872	      if (raioKm && !temFiltroManual) params.set('raio_km', String(raioKm));
873	    }
874	    const qs = params.toString();
875	
876	    // Sem GPS ao vivo (negado/indisponível) e logado: manda o token pro backend usar o
877	    // endereço salvo/geocodificado do perfil como fallback (ver catalogo.controller.ts).
878	    (async () => {
879	      const headers = {};
880	      if (isAuthenticated()) {
881	        const { data: { session } } = await supabase.auth.getSession().catch(() => ({ data: {} }));
882	        if (session?.access_token) headers.Authorization = `Bearer ${session.access_token}`;
883	      }
884	      try {
885	        const r = await fetch(apiPath(`/api/r${qs ? `?${qs}` : ''}`), { headers });
886	        const d = await r.json();
887	        setRestaurantes(d.restaurantes ?? []);
888	      } catch (e) {
889	        setErro(e.message);
890	      } finally {
891	        setLoading(false);
892	      }
893	    })();
894	  }, [statusLocalizacao, localizacao, raioKm, filtroEstado, filtroCidade, filtroBairro, filtroCep, temFiltroManual]);
895	
896	  // Chip sintético de combo junto das categorias reais — não tem category_id, é
897	  // tratado à parte (ver mostrandoCombos) pra trocar o conteúdo da seção de produtos.
