import { Controller, Get, Headers, NotFoundException, Param, Query } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';
import { SupabaseJwtService } from '../auth/supabase-jwt.service';
import { RedisService } from '../redis/redis.service';
import { haversineKm } from '../common/geo.util';
import { normalizarDominio } from '../common/dominio.util';
import { CombosService } from '../combos/combos.service';
import { DEFAULT_APARENCIA_MARKETPLACE } from '../plataforma/aparencia-marketplace.constants';
import * as os from 'os';

const PRODUTO_FIELDS = 'id, name, description, price, preco_promo, image_url, category_id, restaurant_id, tags, destaque, is_active, quantidade_estoque';
const RAIO_KM_PADRAO = 15;

// TTL curto: aceita alguns segundos de defasagem de estoque/preço no marketplace
// público em troca de menos carga no Supabase (mesmo trade-off que iFood/Rappi fazem).
const TTL_CARDAPIO = 15;
const TTL_FILTROS = 60;

@Controller('r')
export class CatalogoController {
  constructor(
    private supabase: SupabaseService,
    private supabaseJwt: SupabaseJwtService,
    private combosService: CombosService,
    private redis: RedisService,
  ) {}

  // Público — branding do marketplace (logo/hero/cores) editado em /admin/aparencia.
  @Get('branding')
  async getBranding() {
    const { data } = await this.supabase.client
      .from('platform_settings')
      .select('config')
      .eq('id', 1)
      .maybeSingle();

    const cfg = (data?.config ?? {}) as Record<string, any>;
    return { ...DEFAULT_APARENCIA_MARKETPLACE, ...(cfg.aparencia_marketplace ?? {}) };
  }

  @Get('acesso')
  async getAcesso() {
    const nets = os.networkInterfaces();
    const todos: string[] = [];
    for (const iface of Object.values(nets)) {
      for (const net of iface ?? []) {
        if (net.family === 'IPv4' && !net.internal) todos.push(net.address);
      }
    }
    // Prioriza 192.168.x.x (WiFi doméstico/corporativo) e 10.x.x.x (redes corporativas).
    // Descarta 172.16-31.x.x que são WSL, Docker, Hyper-V — não acessíveis por dispositivos reais.
    const score = (ip: string) => {
      if (/^192\.168\./.test(ip)) return 0;
      if (/^10\./.test(ip)) return 1;
      if (/^172\.(1[6-9]|2\d|3[01])\./.test(ip)) return 99; // virtual — vai por último
      return 2;
    };
    const ips = todos.sort((a, b) => score(a) - score(b));

    const { data } = await this.supabase.client
      .from('platform_settings')
      .select('config')
      .eq('id', 1)
      .maybeSingle();
    const cfg = ((data?.config ?? {}) as Record<string, any>);
    return {
      lan_ips: ips,
      porta: 4028,
      cloudflare_domain: cfg.cloudflare_domain || null,
    };
  }

  @Get()
  async listarRestaurantes(
    @Query()
    query: {
      state?: string;
      city?: string;
      neighborhood?: string;
      cep?: string;
      lat?: string;
      lng?: string;
      raio_km?: string;
    },
    @Headers('authorization') authorization?: string,
  ) {
    // Sem Authorization o resultado é puramente função da querystring — cacheável.
    // Com Authorization pode depender do endereço salvo do cliente (personalizado), então
    // nesse caso sempre busca direto no Supabase, igual já fazia antes do cache.
    const cacheKey = !authorization
      ? `catalogo:home:${JSON.stringify(query, Object.keys(query).sort())}`
      : null;

    if (cacheKey) {
      const cached = await this.redis.getJSON<{ restaurantes: any[] }>(cacheKey);
      if (cached) return cached;
    }

    let q = this.supabase.client
      .from('restaurants')
      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, aparencia, frete_motoboy, lat, lng')
      .not('slug', 'is', null)
      .eq('bloqueado', false)
      .eq('modulo_delivery', true);

    if (query.state) q = q.ilike('state', query.state);
    if (query.city) q = q.ilike('city', query.city);
    if (query.neighborhood) q = q.ilike('neighborhood', query.neighborhood);
    if (query.cep) q = q.ilike('cep', `${query.cep.replace(/\D/g, '').slice(0, 5)}%`);

    const { data, error } = await q.order('name');
    if (error) throw error;

    let restaurantes = data ?? [];

    // Filtro/ordenação por proximidade — GPS ao vivo do navegador é a fonte principal
    // (comportamento esperado: cliente abre o site, mostra estabelecimentos perto de onde
    // ele está agora). Só cai pro endereço salvo/geocodificado do perfil (ver PerfilService)
    // quando o navegador não mandou lat/lng (GPS negado/indisponível) e o cliente tem token
    // válido — nunca confia numa coordenada de "fallback" vinda do próprio client.
    let lat = query.lat ? parseFloat(query.lat) : null;
    let lng = query.lng ? parseFloat(query.lng) : null;
    let usandoEnderecoSalvo = false;

    if (lat == null && lng == null && authorization?.startsWith('Bearer ')) {
      const token = authorization.slice('Bearer '.length);
      const payload = await this.supabaseJwt.verificar(token);
      if (payload?.sub) {
        const { data: customer } = await this.supabase.client
          .from('customers')
          .select('lat, lng')
          .eq('user_id', payload.sub)
          .maybeSingle();
        if (customer?.lat != null && customer?.lng != null) {
          lat = customer.lat;
          lng = customer.lng;
          usandoEnderecoSalvo = true;
        }
      }
    }

    if (lat != null && lng != null && !Number.isNaN(lat) && !Number.isNaN(lng)) {
      const raioKm = query.raio_km ? parseFloat(query.raio_km) : (usandoEnderecoSalvo ? RAIO_KM_PADRAO : null);
      restaurantes = restaurantes
        .map((r) => ({
          ...r,
          // 3 casas decimais (precisão de metro) — raios pequenos (20m, 50m...)
          // precisavam de mais que os 100m que 1 casa decimal dava.
          distancia_km:
            r.lat != null && r.lng != null
              ? Math.round(haversineKm({ lat, lng }, { lat: r.lat, lng: r.lng }) * 1000) / 1000
              : null,
        }))
        .filter((r) => raioKm == null || (r.distancia_km != null && r.distancia_km <= raioKm))
        .sort((a, b) => (a.distancia_km ?? Infinity) - (b.distancia_km ?? Infinity));
    }

    const resultado = { restaurantes };
    if (cacheKey) await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
    return resultado;
  }

  // Valores distintos de estado/cidade/bairro entre restaurantes ativos — alimenta os
  // dropdowns em cascata do filtro geográfico na home pública (evita carregar tudo só
  // pra montar as opções). Precisa vir ANTES de @Get(':slug') na ordem das rotas.
  @Get('filtros')
  async filtrosGeograficos() {
    const cacheKey = 'catalogo:filtros';
    const cached = await this.redis.getJSON<{ locais: any[] }>(cacheKey);
    if (cached) return cached;

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .select('state, city, neighborhood')
      .not('slug', 'is', null)
      .eq('bloqueado', false)
      .eq('modulo_delivery', true);
    if (error) throw error;

    const vistos = new Set<string>();
    const locais: { state: string | null; city: string | null; neighborhood: string | null }[] = [];
    for (const r of data ?? []) {
      if (!r.state && !r.city && !r.neighborhood) continue;
      const key = `${r.state ?? ''}|${r.city ?? ''}|${r.neighborhood ?? ''}`;
      if (vistos.has(key)) continue;
      vistos.add(key);
      locais.push({ state: r.state, city: r.city, neighborhood: r.neighborhood });
    }
    const resultado = { locais };
    await this.redis.setJSON(cacheKey, resultado, TTL_FILTROS);
    return resultado;
  }

  @Get('produtos')
  async todosOsProdutos() {
    const cacheKey = 'catalogo:produtos:marketplace';
    const cached = await this.redis.getJSON<{ produtos: any[] }>(cacheKey);
    if (cached) return cached;

    const { data: restaurantes } = await this.supabase.client
      .from('restaurants')
      .select('id, name, logo_url, slug, aparencia, frete_motoboy, pagamento_manual, payment_config')
      .not('slug', 'is', null)
      .eq('bloqueado', false)
      .eq('modulo_delivery', true);

    if (!restaurantes?.length) return { produtos: [] };

    const restIds = restaurantes.map((r) => r.id);
    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, this.exporPagamentoPublico(r)]));

    // Busca diretamente por restaurant_id (não depende de category chain)
    const { data: produtos, error } = await this.supabase.client
      .from('products')
      .select(PRODUTO_FIELDS)
      .eq('is_active', true)
      .gt('quantidade_estoque', 0)
      .in('restaurant_id', restIds)
      .order('name')
      .limit(200);

    if (error) throw error;

    const resultado = {
      produtos: (produtos ?? []).map((p) => ({
        ...p,
        restaurante: restMap[p.restaurant_id] ?? null,
      })).filter((p) => p.restaurante),
    };
    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
    return resultado;
  }

  // Marketplace (home sem domínio customizado): combo ativo de todos os
  // estabelecimentos, com estoque de todo ingrediente — mesmo critério
  // de disponibilidade do CombosService, só que sem restringir a 1 restaurante.
  @Get('combos')
  async todosOsCombos() {
    const cacheKey = 'catalogo:combos:marketplace';
    const cached = await this.redis.getJSON<{ combos: any[] }>(cacheKey);
    if (cached) return cached;

    const { data: restaurantes } = await this.supabase.client
      .from('restaurants')
      .select('id, name, logo_url, slug, aparencia, frete_motoboy, pagamento_manual, payment_config')
      .not('slug', 'is', null)
      .eq('bloqueado', false)
      .eq('modulo_delivery', true);

    if (!restaurantes?.length) return { combos: [] };

    const restIds = restaurantes.map((r) => r.id);
    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, this.exporPagamentoPublico(r)]));

    const { data: combos, error } = await this.supabase.client
      .from('combos')
      .select(
        'id, name, description, price, preco_promo, image_url, destaque, restaurant_id, is_active, combo_items(quantity, products(quantidade_estoque, is_active))',
      )
      .eq('is_active', true)
      .in('restaurant_id', restIds)
      .order('destaque', { ascending: false })
      .order('name')
      .limit(200);

    if (error) throw error;

    const resultado = {
      combos: (combos ?? [])
        .map((c: any) => {
          const { combo_items, ...resto } = c;
          const itens = combo_items ?? [];
          const disponivel =
            itens.length > 0 &&
            itens.every((ci: any) => ci.products?.is_active && (ci.products?.quantidade_estoque ?? 0) > 0);
          return { ...resto, disponivel, restaurante: restMap[c.restaurant_id] ?? null };
        })
        .filter((c: any) => c.disponivel && c.restaurante),
    };
    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
    return resultado;
  }

  // Resolução de domínio customizado — precisa vir ANTES de @Get(':slug') na
  // ordem das rotas (mesma regra de 'filtros'/'produtos' acima).
  @Get('by-domain/:host')
  async cardapioPorDominio(@Param('host') host: string) {
    const dominio = normalizarDominio(host);
    const cacheKey = `catalogo:cardapio:dominio:${dominio}`;
    const cached = await this.redis.getJSON<any>(cacheKey);
    if (cached) return cached;

    const { data: restaurante } = await this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy, modulo_delivery, pagamento_manual, payment_config')
      .eq('custom_domain', dominio)
      .maybeSingle();

    if (!restaurante) throw new NotFoundException('Domínio não configurado');
    const resultado = await this.montarCardapio(restaurante);
    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
    return resultado;
  }

  @Get(':slug')
  async cardapio(@Param('slug') slug: string) {
    const cacheKey = `catalogo:cardapio:${slug}`;
    const cached = await this.redis.getJSON<any>(cacheKey);
    if (cached) return cached;

    const { data: restaurante } = await this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy, modulo_delivery, pagamento_manual, payment_config')
      .eq('slug', slug)
      .maybeSingle();

    if (!restaurante) throw new NotFoundException('Restaurante não encontrado');
    const resultado = await this.montarCardapio(restaurante);
    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
    return resultado;
  }

  // payment_config nunca sai em claro (token PagBank etc) — só a chave PIX é pública,
  // e só quando o restaurante está em modo manual (checkout gera o QR local com ela).
  private exporPagamentoPublico(r: any) {
    const chave_pix = r.pagamento_manual ? (r.payment_config?.chave_pix ?? null) : null;
    const { payment_config, ...resto } = r;
    return { ...resto, chave_pix };
  }

  private async montarCardapio(restauranteRaw: any) {
    const restaurante = this.exporPagamentoPublico(restauranteRaw);

    // Categorias do restaurante (próprias + globais para exibição)
    const { data: categorias } = await this.supabase.client
      .from('categories')
      .select('id, name')
      .or(`restaurant_id.eq.${restaurante.id},restaurant_id.is.null`)
      .order('name');

    // Produtos via restaurant_id (forma correta e direta)
    const { data: produtos } = await this.supabase.client
      .from('products')
      .select(PRODUTO_FIELDS)
      .eq('is_active', true)
      .gt('quantidade_estoque', 0)
      .eq('restaurant_id', restaurante.id)
      .order('destaque', { ascending: false })
      .order('name');

    const cardapio = (categorias ?? []).map((cat) => ({
      ...cat,
      produtos: (produtos ?? []).filter((p) => p.category_id === cat.id),
    })).filter((cat) => cat.produtos.length > 0);

    const destaques = (produtos ?? []).filter((p) => p.destaque);
    const promos = (produtos ?? []).filter(
      (p) => Array.isArray(p.tags) && p.tags.includes('promo') && p.preco_promo != null,
    );

    // Combos são entidade separada de products — mesmos campos de exibição
    // (name/price/preco_promo/image_url/destaque) pra reusar o mesmo card do cliente.
    // Some do cardápio se faltar estoque de qualquer produto que o compõe.
    const combosDisponiveis = await this.combosService.listarComDisponibilidade(restaurante.id);
    const combos = combosDisponiveis.filter((c) => c.disponivel).map((c) => ({ ...c, tipo: 'combo' }));

    return { restaurante, cardapio, destaques, promos, combos };
  }
}

